Object.assign(window.LIT_VERSES,{"mutanabbi-azm-005":{"id":"mutanabbi-azm-005","poemId":"ala-qadr-ahl-al-azm","order":5,"first":"تُفَدّي أَتَمُّ الطَيرِ عُمرًا سِلاحَهُ","second":"نُسورُ الفَلا أَحداثُها وَالقَشاعِمُ","meaning":"يتخيل المتنبي النسور، صغيرها ومسنها، وهي تفدي سلاح سيف الدولة؛ لأن كثرة ما يوقعه السلاح من قتلى تكفيها مؤنة طلب الطعام. فبدل أن يصف كثرة القتل مباشرة، يصور أثره في الطير التي تقتات من الجثث.","vocabulary":[{"term":"أتم الطير عمرًا","text":"أطول الطير عمرًا في سياق البيت، وقد ناقش ابن سيده اختيار «أتم» من جهة اللغة والوزن."},{"term":"أحداثها","text":"صغار النسور وحديثها سنًا."},{"term":"القشاعم","text":"المسان من النسور."},{"term":"تفدي","text":"تقول: جعلنا أنفسنا فداءً لك؛ وهو تخييل يجعل النسور كأنها ناطقة بالشكر."}],"syntax":["«أتم الطير عمرًا» هو المسند إليه في «تفدي»، و«عمرًا» تمييز يوضح جهة التمام.","«نسور الفلا» تفسير لأتم الطير، ثم «أحداثها والقشاعم» تفصيل لطرفي العمر؛ وقد ناقش ابن سيده أوجه البدل في هذا التركيب."],"morphology":["«أتمّ» اسم تفضيل من «تمّ»، و«عمرًا» تمييز يبين جهة التمام. وقد وقف ابن سيده عند هذا الاختيار لأن المتوقع في العمر «أطول»، وربطه بما يستقيم معه الوزن.","«أحداث» جمع «حدث» بمعنى صغير السن، في مقابل «القشاعم» وهي المسان من النسور؛ فالمعجم الصرفي نفسه يقسم الطير إلى طرفي العمر.","«تفدي» من الفداء، وإسنادها إلى الطير ينقل فعلًا إنسانيًا إراديًا إلى النسور، وهو أساس التشخيص في الصورة."],"rhetoric":{"thesis":"هذا البيت ينقلنا من مديح مباشر إلى تصوير أثر الحرب. البلاغة هنا في زاوية الرؤية: الشاعر لا يرينا المقتولين أولًا؛ يرينا كائنات تعيش على نتيجة القتل.","devices":[{"title":"قلب زاوية الوصف","text":"بدل قول «كثر قتلاه»، يجعل النسور هي المتكلمة المستفيدة من السلاح. النتيجة أبلغ لأن القارئ يستنتج كثرة القتلى من أثرها، لا من تصريح الشاعر بها."},{"title":"تشخيص النسور","text":"الفعل «تفدي» من أفعال الكائن العاقل المتكلم، فنُقلت النسور إلى مقام من يشكر السلاح ويفديه. هذا التشخيص يزيد غرابة الصورة وقسوتها في آن واحد."},{"title":"استيعاب طرفي العمر","text":"«أحداثها والقشاعم» يجمع الصغار والمسان، أي إن أثر الحرب بلغ كل النسور. التقابل العمري هنا وسيلة للمبالغة في الشمول."},{"title":"لفظة «أتم» ومقاومة السطحية","text":"ابن سيده يقف عند «أتم» لأنها ليست اللفظة المتوقعة مع العمر مثل «أطول»، ويربط الاختيار بإمكان الوزن. هذا مثال لما يجب أن يفعله الشرح المتعمق: لا يمر على اللفظ الغريب كأنه عادي."}],"connection":"البيت السادس يفسر الصورة ويذهب بها أبعد: حتى ضعف مخالب النسور لا يضرها، لأن أسياف سيف الدولة تقوم مقام وسيلة الصيد."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"اختيار «أتم» بدل «أطول» ناقشه ابن سيده من جهة سلامة الوزن؛ وهذه ملاحظة مهمة لأنها تصل المعجم بالعروض بدل فصل أحدهما عن الآخر."},"context":"بداية مقطع تصوير آثار الحرب من خلال النسور، بعد أربعة أبيات كانت أقرب إلى الحكمة والمدح المباشر.","sourceIds":["wahidi-274","ibn-sidah-70","ibn-aliflili-483"]},"mutanabbi-azm-006":{"id":"mutanabbi-azm-006","poemId":"ala-qadr-ahl-al-azm","order":6,"first":"وَما ضَرَّها خَلقٌ بِغَيرِ مَخالِبٍ","second":"وَقَد خُلِقَت أَسيافُهُ وَالقَوائِمُ","meaning":"لا يضر النسور — ولا سيما صغارها ومسانها الضعيفة — أن تكون بلا مخالب قوية للصيد، ما دامت أسياف سيف الدولة تكثر لها الجثث. و«القوائم» هنا جمع قائم السيف؛ أي مقبضه، لا قوائم الحيوان.","vocabulary":[{"term":"المخالب","text":"ما تصيد به الجوارح وتمسك الفريسة."},{"term":"القوائم","text":"جمع قائم السيف؛ أي مقبضه. هذه دلالة لغوية مهمة لأن القراءة الحديثة قد تتوهم الأرجل."},{"term":"خلق بغير مخالب","text":"أي كونها مخلوقة من غير مخالب قوية مفترسة؛ والبيت يبني على صورة النسور في البيت السابق."}],"syntax":["يمكن فهم «ما» على النفي، ويذكر الشراح إمكان حمل العبارة على معنى الاستفهام الإنكاري: ما الذي كان سيضرها لو خُلقت بلا مخالب؟","جملة «وقد خلقت أسيافه والقوائم» حالية تعلل انتفاء الضرر: السلاح قائم بوظيفة توفير القوت."],"morphology":["«مخالب» جمع «مِخلب»، وهو اسم آلة من الخلب/الأخذ، فدلالته مرتبطة بوظيفة الصيد والإمساك.","«أسياف» جمع «سيف»، و«القوائم» جمع «قائم» في معنى قائم السيف أي مقبضه؛ ولا يصح هنا حملها على قوائم الحيوان.","البناء للمجهول في «خُلقت» يوجه الانتباه إلى هيئة الخِلقة نفسها لا إلى فاعل الخلق، لأن المقارنة منصبة على الأداة الطبيعية في مقابل السلاح."],"rhetoric":{"thesis":"البيت لا يضيف صورة جديدة منفصلة، بل يكمل منطق الصورة السابقة: النسور لا تحتاج أدوات الصيد لأن الحرب نفسها صارت أداة إطعامها.","devices":[{"title":"المفارقة القاسية","text":"المخلب، وهو أداة طبيعية للصيد، يصبح غير ضروري لأن سيف الإنسان يؤدي الوظيفة على نطاق أكبر. هكذا يتحول المدح الحربي إلى صورة لا تخفي عنف الحرب."},{"title":"السبب بعد النتيجة","text":"في البيت السابق رأينا النسور تفدي السلاح، وهنا نعرف السبب: السلاح أغناها عن الصيد. هذا الربط يجعل البيتين وحدة تصويرية واحدة لا بيتين مستقلين."},{"title":"دقة اللفظ «القوائم»","text":"المعنى يختل إن فُهمت القوائم على أنها أرجل. المقصود مقابض السيوف، أي إن السلاح مكتمل بأصوله وأجزائه وجاهز للعمل. هذه نقطة لغوية يجب أن تظهر للقارئ قبل أي تأويل بلاغي."},{"title":"المدح بطريق الأثر","text":"لا يقول: سيف الدولة كثير القتل. يجعل أثر سلاحه في نظام غذاء النسور دليلًا على كثرة الوقائع. هذه طريقة تصويرية غير مباشرة أقوى من التقرير."}],"connection":"بعد اكتمال صورة النسور، ينتقل البيت السابع إلى مركز الواقعة نفسه: قلعة الحدث، فيسألها عن لونها كأنها كائن يتذكر."},"prosody":{"meter":"البحر الطويل","rhyme":"الروي ميم مضمومة","note":"التقابل بين «مخالب» و«أسيافه والقوائم» يضع أداة صيد الحيوان بإزاء أداة قتل الإنسان، وهو تقابل دلالي يدعم الصورة أكثر من كونه مجرد محسن لفظي."},"context":"البيت الثاني من لوحة النسور، ووظيفته تفسير الصورة السابقة وتكثيف دلالة كثرة القتلى.","sourceIds":["wahidi-274","barquqi-162-170","ibn-aliflili-483"]}});